def transform(grid):
    out = [row[:] for row in grid]
    # Extend each colored vertical stroke through the gray cells above it.
    for c in (11, 13, 15, 17):
        color = 0
        for r in range(4, 0, -1):
            if out[r][c] not in (0, 5):
                color = out[r][c]
            elif out[r][c] == 5 and color:
                out[r][c] = color
    # Move the gray pattern ten columns right and clear its source.
    for r in range(len(grid)):
        for c in range(8):
            if grid[r][c] == 5:
                out[r][c + 10] = 5
            out[r][c] = 0
    return out
